edits.after:
/* Keep percentage-sized controls inside definite-height flip wrappers. */
.coverflip-viewsides,
.coverflip-side.front {
  height: 100%;
}
.coverflip-container {
  height: 100%;

/* This control has positioned children, not table cells. */
.dimabs-container {
  display: block;
  margin: 0 auto;
}
